const now = new Date();
const pad = n => String(n).padStart(2, '0');

const stamp =
  now.getUTCFullYear() +
  pad(now.getUTCMonth() + 1) +
  pad(now.getUTCDate()) +
  '-' +
  pad(now.getUTCHours()) +
  pad(now.getUTCMinutes()) +
  pad(now.getUTCSeconds());

const run_id = `RUN-${stamp}`;

return [{
  json: {
    run_id,
    run_doc_id: `run:${run_id}`,
    run_started_at: now.toISOString(),
    type: 'run',
    status: 'started',
    workflow: 'Dive Lead Discovery + <COUCHDB_CREDENTIAL_NAME> Persistence V1',
    started_at: now.toISOString()
  }
}];

const ctx = $('Create Run Context').item.json;
const status = Number($json.statusCode || 0);

if (status && status >= 400) {
  throw new Error(`Could not create run document in CouchDB. Status: ${status}`);
}

return [{ json: ctx }];

const j = $json;
const packet = j.research_packet || {};

function asText(value) {
  if (typeof value === 'string') return value;
  if (value == null) return '';
  try { return JSON.stringify(value); } catch { return String(value); }
}

function cleanEmail(value) {
  if (!value) return '';

  const e = String(value)
    .trim()
    .toLowerCase()
    .replace(/^mailto:/i, '')
    .split('?')[0]
    .trim();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) return '';
  if (/^(noreply|no-reply|donotreply|do-not-reply|example|test)@/i.test(e)) return '';
  if (e.includes('@example.')) return '';

  return e;
}

function normalizeInstagramUrl(value) {
  if (!value) return '';

  let s = String(value)
    .trim()
    .replace(/\\\//g, '/')
    .replace(/[)\],.'"]+$/g, '')
    .replace(/^http:\/\//i, 'https://');

  if (!/^https?:\/\/(www\.)?instagram\.com\//i.test(s)) return '';

  const lower = s.toLowerCase();

  if (/instagram\.com\/(p|reel|stories|explore|accounts)\//i.test(lower)) {
    return '';
  }

  s = s.split('?')[0].split('#')[0];

  if (!s.endsWith('/')) s += '/';

  return s;
}

function extractEmails(text) {
  return [
    ...new Set(
      (String(text || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
        .map(cleanEmail)
        .filter(Boolean)
    )
  ];
}

function extractInstagram(text) {
  const out = new Set();
  const safeText = String(text || '').replace(/\\\//g, '/');

  const urlMatches =
    safeText.match(/https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9_.]+\/?/gi) || [];

  for (const raw of urlMatches) {
    const clean = normalizeInstagramUrl(raw);
    if (clean) out.add(clean);
  }

  const handleRegex = /\b(?:instagram|ig)\s*[:：]\s*@([a-z0-9._]{2,30})/gi;
  let match;

  while ((match = handleRegex.exec(safeText)) !== null) {
    out.add(`https://www.instagram.com/${match[1].toLowerCase()}/`);
  }

  return [...out];
}

function unique(values) {
  return [...new Set((values || []).filter(Boolean).map(v => String(v).trim()).filter(Boolean))];
}

let text = '';

text += '\n' + asText(packet.homepage);

for (const p of (packet.pages || [])) {
  text += '\n' + asText(p.url);
  text += '\n' + asText(p.markdown);
}

const public_emails = unique([
  ...(j.public_emails_found || []),
  ...(j.homepage_emails || []),
  ...(j.mailto_emails || []),
  ...(packet.public_emails_found || []),
  ...(packet.homepage_emails || []),
  ...(packet.mailto_emails || []),
  ...extractEmails(text)
]).map(cleanEmail).filter(Boolean).slice(0, 20);

function likelyGeneric(email) {
  const local = String(email || '').split('@')[0].toLowerCase();
  return /^(info|hello|contact|sales|travel|trips|reservations|booking|bookings|enquiries|enquiry|admin|office|support|team)$/.test(local);
}

const instagram_links = unique([
  ...(j.instagram_links || []),
  ...(j.social_links?.instagram || []),
  ...(j.contact_hints?.instagram_links || []),
  ...(packet.instagram_links || []),
  ...(packet.social_links?.instagram || []),
  ...extractInstagram(text)
]).map(normalizeInstagramUrl).filter(Boolean).slice(0, 10);

const contact_email_hints = public_emails.map(email => ({
  public_email: email,
  role: likelyGeneric(email) ? 'generic_public_inbox' : 'public_email',
  source: 'website_text_regex'
}));

const contact_hints = {
  ...(j.contact_hints || {}),
  ...(packet.contact_hints || {}),
  public_emails,
  contact_email_hints,
  instagram_links
};

const social_links = {
  ...(j.social_links || {}),
  ...(packet.social_links || {}),
  instagram: instagram_links
};

return [
  {
    json: {
      ...j,
      public_emails_found: public_emails,
      instagram_links,
      social_links,
      research_packet: {
        ...packet,
        contact_hints,
        public_emails_found: public_emails,
        instagram_links,
        social_links
      },
      contact_hints
    }
  }
];

const allInputs = $input.all();

let j =
  allInputs.find(item =>
    item.json?.domain ||
    item.json?.website ||
    item.json?.company_name
  )?.json ||
  allInputs[0]?.json ||
  {};

// Defensive unwrap in case n8n passes a nested object/array
if (Array.isArray(j)) {
  j = j[0] || {};
}

if (j.json && typeof j.json === 'object') {
  j = j.json;
}

if (j.body && typeof j.body === 'object') {
  j = j.body;
}

function canonicalDomain(value) {
  if (!value) return '';

  let s = String(value).trim().toLowerCase();

  // Remove quotes/spaces
  s = s.replace(/^['"]|['"]$/g, '').trim();

  // Remove protocol
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');

  // Remove protocol-relative //
  s = s.replace(/^\/\//, '');

  // Remove user/pass if ever present
  s = s.replace(/^.*@/, '');

  // Keep hostname only
  s = s.split(/[/?#]/)[0];

  // Remove port
  s = s.replace(/:\d+$/, '');

  // Remove www and trailing dot
  s = s
    .replace(/^www\./, '')
    .replace(/\.$/, '');

  // Remove accidental whitespace
  s = s.trim();

  // Basic validation
  if (!s || !s.includes('.')) return '';
  if (!/^[a-z0-9.-]+$/.test(s)) return '';

  return s;
}

function cleanEmail(value) {
  if (!value) return '';

  const e = String(value).trim().toLowerCase();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) return '';
  if (/^(noreply|no-reply|donotreply|do-not-reply)@/i.test(e)) return '';

  return e;
}

function normalizeName(value) {
  return String(value || '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function slug(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function localPartRole(email) {
  const local = String(email || '').split('@')[0].toLowerCase();

  if (/^(info|hello|contact|sales|travel|trips|reservations|booking|bookings|enquiries|enquiry|admin|office|support|team)$/.test(local)) {
    return 'generic_public_inbox';
  }

  return 'published_email';
}

const domainInput =
  j.domain ||
  j.website ||
  j.canonical_domain ||
  j.company_website ||
  '';

const domain = canonicalDomain(domainInput);

if (!domain) {
  throw new Error(
    'Unable to determine company domain. Debug input: ' +
    JSON.stringify({
      picked_input: domainInput,
      domain: j.domain,
      website: j.website,
      canonical_domain: j.canonical_domain,
      company_website: j.company_website,
      company_name: j.company_name,
      available_keys: Object.keys(j || {})
    })
  );
}

const company_id = `company:${domain}`;

const rawContacts = [];

// Contacts from DeepSeek / research output
for (const c of (j.contacts_found || [])) {
  if (!c || typeof c !== 'object') continue;
  rawContacts.push(c);
}

// Public emails scraped from site
for (const email of (j.public_emails_found || [])) {
  const cleaned = cleanEmail(email);

  if (!cleaned) continue;

  rawContacts.push({
    name: '',
    title: '',
    role: localPartRole(cleaned),
    public_email: cleaned,
    source: 'public_site_email'
  });
}

// Optional contact hints
for (const h of (j.contact_hints?.contact_email_hints || [])) {
  if (!h || typeof h !== 'object') continue;
  rawContacts.push(h);
}

const seenContactKeys = new Set();
const contact_candidates = [];

for (const raw of rawContacts) {
  const email = cleanEmail(raw.public_email || raw.email);
  const name = String(raw.name || '').trim().replace(/\s+/g, ' ');
  const normalized_name = normalizeName(name);
  const title = String(raw.title || raw.job_title || '').trim();
  const role = String(raw.role || raw.role_category || '').trim();

  let contact_id = '';

  if (email) {
    contact_id = `contact:${email}`;
  } else if (normalized_name && normalized_name.split(' ').length >= 2) {
    contact_id = `contact:${domain}:${slug(normalized_name)}`;
  } else {
    continue;
  }

  if (seenContactKeys.has(contact_id)) continue;
  seenContactKeys.add(contact_id);

  const is_generic =
    email ? localPartRole(email) === 'generic_public_inbox' : false;

  contact_candidates.push({
    _id: contact_id,
    type: 'contact',
    company_id,
    name: name || email || '',
    normalized_name,
    job_title: title,
    role_category: role || (email ? localPartRole(email) : 'published_person'),
    email: email || null,
    email_status: email ? 'published' : 'unknown',
    contact_score: email ? (is_generic ? 55 : 85) : 45,
    is_primary: false,
    source: raw.source || 'deepseek_or_public_site'
  });
}

if (contact_candidates.length) {
  contact_candidates.sort(
    (a, b) => Number(b.contact_score || 0) - Number(a.contact_score || 0)
  );

  contact_candidates[0].is_primary = true;
}

const now = new Date().toISOString();

const run_id =
  j.run_id ||
  j.crm_run_id ||
  `RUN-${now.slice(0, 10).replace(/-/g, '')}-MANUAL`;

return [
  {
    json: {
      ...j,
      crm_normalized_at: now,
      canonical_domain: domain,
      company_id,
      crm_run_id: run_id,
      contact_candidates,
      primary_contact_id: contact_candidates[0]?._id || null
    }
  }
];

const existing = $json.body;
const incoming = $('Normalize CRM Lead').item.json;
const now = new Date().toISOString();

if (!existing?._id || !existing?._rev) {
  throw new Error('Existing company is missing _id or _rev');
}

function priorityRank(p) {
  return ({ S: 5, A: 4, B: 3, C: 2, REJECT: 1 })[String(p || '').toUpperCase()] || 0;
}

const existingPriority = existing.best_priority || existing.priority || '';
const incomingPriority = incoming.priority || '';
const bestPriority = priorityRank(incomingPriority) > priorityRank(existingPriority)
  ? incomingPriority
  : existingPriority;

return [{
  json: {
    ...existing,

    type: 'company',

    canonical_domain: existing.canonical_domain || incoming.canonical_domain,
    company_name: incoming.company_name || existing.company_name || incoming.canonical_domain,
    website: incoming.website || existing.website || `https://${incoming.canonical_domain}`,
    country: incoming.business_country || existing.country || '',

    persona: incoming.persona || existing.persona || '',
    priority: incoming.priority || existing.priority || '',
    lifecycle_status: existing.lifecycle_status || (incoming.priority === 'REJECT' ? 'rejected' : 'new'),

    first_seen_at: existing.first_seen_at || now,
    last_seen_at: now,
    times_discovered: Number(existing.times_discovered || 0) + 1,
    last_run_id: incoming.crm_run_id,

    best_icp_score: Math.max(
      Number(existing.best_icp_score || 0),
      Number(incoming.icp_score || 0)
    ),

    best_intent_score: Math.max(
      Number(existing.best_intent_score || 0),
      Number(incoming.intent_score || 0)
    ),

    best_priority: bestPriority,

    do_not_contact: Boolean(existing.do_not_contact),
    active_contact_id: existing.active_contact_id ?? null,
    last_contacted_at: existing.last_contacted_at ?? null,
    next_contact_allowed_at: existing.next_contact_allowed_at ?? null,

    latest_profile: {
      services: incoming.services || [],
      destinations_sold: incoming.destinations_sold || [],
      intent_signals: incoming.intent_signals || [],
      evidence: incoming.evidence || [],
      reason: incoming.reason || '',
      personalized_first_line: incoming.personalized_first_line || ''
    },

    source: {
      discovery_source: incoming.discovery_source || existing.source?.discovery_source || '',
      discovery_query: incoming.discovery_query || existing.source?.discovery_query || ''
    },

    _rev: existing._rev
  }
}];

const status = Number($json.statusCode);

let write_result;

if (status === 201 || status === 202) {
  write_result = 'SUCCESS';
} else if (status === 409) {
  write_result = 'CONFLICT';
} else {
  write_result = 'ERROR';
}

return [{
  json: {
    ...$json,
    write_result,
  },
}];

const latest = $json;
const incoming = $('Normalize CRM Lead').item.json;
const now = new Date().toISOString();

if (!latest?._id || !latest?._rev) {
  throw new Error('Retry: latest company is missing _id or _rev');
}

return [{
  json: {
    ...latest,

    type: 'company',

    canonical_domain: latest.canonical_domain || incoming.canonical_domain,
    company_name: incoming.company_name || latest.company_name || incoming.canonical_domain,
    website: incoming.website || latest.website || `https://${incoming.canonical_domain}`,
    country: incoming.business_country || latest.country || '',

    persona: incoming.persona || latest.persona || '',
    priority: incoming.priority || latest.priority || '',
    lifecycle_status: latest.lifecycle_status || (incoming.priority === 'REJECT' ? 'rejected' : 'new'),

    first_seen_at: latest.first_seen_at || now,
    last_seen_at: now,
    times_discovered: Number(latest.times_discovered || 0) + 1,
    last_run_id: incoming.crm_run_id,

    best_icp_score: Math.max(Number(latest.best_icp_score || 0), Number(incoming.icp_score || 0)),
    best_intent_score: Math.max(Number(latest.best_intent_score || 0), Number(incoming.intent_score || 0)),
    best_priority: latest.best_priority || incoming.priority || '',

    do_not_contact: Boolean(latest.do_not_contact),
    active_contact_id: latest.active_contact_id ?? null,
    last_contacted_at: latest.last_contacted_at ?? null,
    next_contact_allowed_at: latest.next_contact_allowed_at ?? null,

    latest_profile: {
      services: incoming.services || [],
      destinations_sold: incoming.destinations_sold || [],
      intent_signals: incoming.intent_signals || [],
      evidence: incoming.evidence || [],
      reason: incoming.reason || '',
      personalized_first_line: incoming.personalized_first_line || ''
    },

    source: {
      discovery_source: incoming.discovery_source || latest.source?.discovery_source || '',
      discovery_query: incoming.discovery_query || latest.source?.discovery_query || ''
    },

    _rev: latest._rev
  }
}];

const status = Number($json.statusCode);
const retry_result = (status === 201 || status === 202) ? 'SUCCESS' : 'ERROR';

return [{ json: { ...$json, retry_result } }];

const lead = $('Normalize CRM Lead').item.json;
return [{
  json: {
    crm_error: true,
    stage: 'company_upsert',
    company_id: lead.company_id,
    statusCode: $json.statusCode,
    body: $json.body || $json
  }
}];

const company = $json;
const lead = $('Normalize CRM Lead').item.json;
const now = new Date().toISOString();

const contact_candidates = (lead.contact_candidates || []).map(c => ({
  ...c,
  company_id: company._id,
  first_seen_at: now,
  last_seen_at: now
}));

return [{
  json: {
    company_id: company._id,
    company_rev: company._rev,
    canonical_domain: lead.canonical_domain,
    contact_ids: contact_candidates.map(c => c._id),
    contact_candidates
  }
}];

const source = $('Build CRM Contact Keys').item.json;
const rows = $json.rows || $json.body?.rows || [];
const existingById = new Map();

for (const row of rows) {
  if (row?.doc && !row.error) {
    existingById.set(row.id, row.doc);
  }
}

const docs = [];
const now = new Date().toISOString();

for (const incoming of (source.contact_candidates || [])) {
  const existing = existingById.get(incoming._id);

  const doc = {
    ...(existing || {}),
    ...incoming,

    type: 'contact',
    company_id: incoming.company_id,

    name: incoming.name || existing?.name || '',
    normalized_name: incoming.normalized_name || existing?.normalized_name || '',
    job_title: incoming.job_title || existing?.job_title || '',
    role_category: incoming.role_category || existing?.role_category || '',

    email: incoming.email || existing?.email || null,
    email_status: incoming.email ? 'published' : (existing?.email_status || 'unknown'),

    contact_score: Math.max(
      Number(existing?.contact_score || 0),
      Number(incoming.contact_score || 0)
    ),

    is_primary: Boolean(incoming.is_primary || existing?.is_primary),

    first_seen_at: existing?.first_seen_at || now,
    last_seen_at: now,
    source: incoming.source || existing?.source || 'deepseek_or_public_site'
  };

  if (existing?._rev) {
    doc._rev = existing._rev;
  }

  docs.push(doc);
}

return [{
  json: {
    company_id: source.company_id,
    contact_docs: docs,
    contact_count: docs.length,
    primary_contact_id: docs.find(d => d.is_primary)?._id || null
  }
}];

return [{
  json: {
    contact_count: 0,
    primary_contact_id: null,
    note: 'No public contact emails or named contacts were found.'
  }
}];

const lead = $('Normalize CRM Lead').item.json;
const company = $('GET Saved CRM Company').item.json;
const now = new Date().toISOString();

function simpleHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

const randomPart = Math.random().toString(36).slice(2, 8);
const eventKey = simpleHash(`${lead.crm_run_id}|${lead.company_id}|${lead.discovery_source}|${lead.discovery_query}|${now}|${randomPart}`);

return [{
  json: {
    _id: `discovery:${lead.crm_run_id}:${eventKey}`,
    type: 'discovery_event',

    run_id: lead.crm_run_id,
    company_id: lead.company_id,
    company_rev_at_discovery: company._rev || null,

    engine: 'outscraper_crawl4ai_deepseek',
    source: lead.discovery_source || '',
    query: lead.discovery_query || '',

    persona: lead.persona || '',
    priority: lead.priority || '',
    icp_score: Number(lead.icp_score || 0),
    intent_score: Number(lead.intent_score || 0),

    contacts_found_count: (lead.contact_candidates || []).length,
    public_emails_found: (lead.contact_candidates || []).filter(c => c.email).map(c => c.email),

    evidence: lead.evidence || [],
    intent_signals: lead.intent_signals || [],

    discovered_at: now,
    created_at: now
  }
}];

const lead = (() => {
  try {
    return $('Normalize CRM Lead').item.json || {};
  } catch (e) {
    return $json || {};
  }
})();

const company = (() => {
  try {
    return $('GET Saved CRM Company').item.json || {};
  } catch (e) {
    return {};
  }
})();

const now = new Date();

let outreach_eligibility = 'ready';
let hold_reason = '';
let block_reason = '';

function cleanString(value) {
  return String(value ?? '').trim();
}

function sortContactsByQuality(contacts) {
  return [...contacts].sort((a, b) => {
    const scoreA = Number(a.contact_score || 0);
    const scoreB = Number(b.contact_score || 0);

    if (scoreB !== scoreA) return scoreB - scoreA;

    const aGeneric = /^(info|hello|contact|admin|office|support)@/i.test(a.email || '');
    const bGeneric = /^(info|hello|contact|admin|office|support)@/i.test(b.email || '');

    if (aGeneric !== bGeneric) return aGeneric ? 1 : -1;

    return String(a.email || '').localeCompare(String(b.email || ''));
  });
}

const publicEmailContacts = sortContactsByQuality(
  (lead.contact_candidates || []).filter(c => cleanString(c.email))
);

if (company.do_not_contact) {
  outreach_eligibility = 'block';
  block_reason = 'Company is marked do_not_contact';
} else if (String(lead.priority || '').toUpperCase() === 'REJECT') {
  outreach_eligibility = 'block';
  block_reason = 'Lead priority is REJECT';
} else if (company.active_contact_id) {
  outreach_eligibility = 'hold';
  hold_reason = 'Company already has an active contact';
} else if (
  company.next_contact_allowed_at &&
  new Date(company.next_contact_allowed_at) > now
) {
  outreach_eligibility = 'hold';
  hold_reason = `Cooldown active until ${company.next_contact_allowed_at}`;
} else if (!publicEmailContacts.length) {
  outreach_eligibility = 'hold';
  hold_reason = 'No public contact email found';
} else if (!['S', 'A', 'B'].includes(String(lead.priority || '').toUpperCase())) {
  outreach_eligibility = 'hold';
  hold_reason = 'Lead priority is below B';
}

const primary =
  publicEmailContacts[0] ||
  (lead.contact_candidates || [])[0] ||
  null;

const instagram_url =
  (lead.instagram_links || [])[0] ||
  lead.social_links?.instagram?.[0] ||
  lead.contact_hints?.instagram_links?.[0] ||
  '';

function buildSheetRow(contact) {
  return {
    company_name: lead.company_name || '',
    website: lead.website || '',
    domain: lead.canonical_domain || lead.domain || '',
    country: lead.business_country || '',
    priority: lead.priority || '',
    persona: lead.persona || '',
    icp_score: lead.icp_score ?? '',
    intent_score: lead.intent_score ?? '',

    contact_name:
      contact?.name ||
      contact?.email ||
      '',

    contact_title:
      contact?.job_title ||
      contact?.title ||
      contact?.role ||
      '',

    contact_email:
      contact?.email ||
      '',

    phone: lead.phone || '',
    instagram_url,

    personalized_first_line: lead.personalized_first_line || '',
    reason: lead.reason || '',
    discovery_source: lead.discovery_source || lead.source || '',
    discovery_query: lead.discovery_query || lead.source_query || '',
    run_id: lead.crm_run_id || lead.run_id || '',
    crm_company_id: lead.company_id || '',
    crm_contact_id: contact?._id || '',

    outreach_eligibility,
    hold_reason,
    block_reason,
    ready_at: now.toISOString()
  };
}

const sheet_rows = publicEmailContacts.length
  ? publicEmailContacts.map(contact => buildSheetRow(contact))
  : [buildSheetRow(primary)];

const sheet_row = sheet_rows[0];

return {
  json: {
    ...lead,

    outreach_eligibility,
    hold_reason,
    block_reason,

    selected_contact_id: primary?._id || null,
    selected_contact_name: primary?.name || primary?.email || '',
    selected_contact_title: primary?.job_title || primary?.title || primary?.role || '',
    selected_contact_email: primary?.email || '',

