const inputItems = $input.all();
let queryItems = [];

try {
  queryItems = $('Generate Discovery Queries1').all().map(item => item.json || {});
} catch (e) {
  queryItems = [];
}

const rows = [];
const seenPlaceOrDomain = new Set();

function flatten(v) {
  if (v == null) return [];
  if (!Array.isArray(v)) return [v];
  return v.flat(Infinity);
}

function unwrapResponse(j) {
  if (j?.body && typeof j.body === 'object') return j.body;
  return j || {};
}

for (let itemIndex = 0; itemIndex < inputItems.length; itemIndex++) {
  const response = unwrapResponse(inputItems[itemIndex].json || {});
  const qctx = queryItems[itemIndex] || {};

  const data =
    response.data ??
    response.results ??
    response.result ??
    [];

  for (const row of flatten(data)) {
    if (!row || typeof row !== 'object') continue;

    const website = row.site || row.website || row.domain || row.url || null;
    if (!website) continue;

    const dedupeKey = String(row.place_id || website).trim().toLowerCase();
    if (!dedupeKey || seenPlaceOrDomain.has(dedupeKey)) continue;
    seenPlaceOrDomain.add(dedupeKey);

    rows.push({
      json: {
        run_id: qctx.run_id || row.run_id || '',
        run_doc_id: qctx.run_doc_id || row.run_doc_id || '',
        run_started_at: qctx.run_started_at || '',

        company_name: row.name || row.title || '',
        website,

        source: 'outscraper_maps',
        source_query: row.query || qctx.query || '',
        discovery_source: 'outscraper_maps',
        discovery_query: row.query || qctx.query || '',
        target_country: qctx.target_country || '',
        region: qctx.region || '',
        language: qctx.language || '',

        business_country: row.country || row.country_code || qctx.target_country || '',
        full_address: row.full_address || row.address || '',
        category: row.category || row.type || '',
        phone: row.phone || row.phone_number || '',
        place_id: row.place_id || '',
        rating: row.rating ?? null,
        reviews: row.reviews ?? row.reviews_count ?? null
      }
    });
  }
}

return rows;

const EXCLUDED = [
  'japan',
  'indonesia',
  'south korea',
  'republic of korea',
  'thailand',
  'maldives',
  'spain'
];

function normalizeWebsite(value) {
  if (!value) return null;

  let s = String(value).trim().toLowerCase();

  // Remove quotes
  s = s.replace(/^['"]|['"]$/g, '').trim();

  // Add fake protocol only for easier text handling, not URL parsing
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');
  s = s.replace(/^\/\//, '');

  // Remove user/pass if present
  s = s.replace(/^.*@/, '');

  // Keep hostname only
  s = s.split(/[/?#]/)[0];

  // Remove port
  s = s.replace(/:\d+$/, '');

  // Remove www and trailing dot
  s = s
    .replace(/^www\./, '')
    .replace(/\.$/, '')
    .trim();

  // Basic validation
  if (!s || !s.includes('.')) return null;
  if (!/^[a-z0-9.-]+$/.test(s)) return null;

  return {
    website: `https://${s}`,
    domain: s
  };
}

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const n = normalizeWebsite(j.website);

  if (!n) {
    continue;
  }

  if (seen.has(n.domain)) {
    continue;
  }

  const locationText = `${j.business_country || ''} ${j.full_address || ''}`.toLowerCase();

  if (EXCLUDED.some(country => locationText.includes(country))) {
    continue;
  }

  seen.add(n.domain);

  out.push({
    json: {
      ...j,
      website: n.website,
      domain: n.domain
    }
  });
}

// First live test cap.
// This limits how many companies continue to Crawl4AI + DeepSeek.
const RAW_DOMAIN_POOL_PER_RUN = 50; // enough variety before CRM skip, still budget-safe
return out.slice(0, RAW_DOMAIN_POOL_PER_RUN);

const crawlItems = $input.all();

function firstResult(obj) {
  if (Array.isArray(obj)) return obj[0] || {};
  if (Array.isArray(obj?.results)) return obj.results[0] || {};
  if (Array.isArray(obj?.data)) return obj.data[0] || {};
  if (obj?.result) return Array.isArray(obj.result) ? (obj.result[0] || {}) : obj.result;
  return obj?.data || obj || {};
}

function hostFromUrl(value) {
  if (!value) return '';

  let s = String(value).trim().toLowerCase();

  if (s.startsWith('mailto:') || s.startsWith('tel:')) return '';

  s = s.replace(/^['"]|['"]$/g, '').trim();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');
  s = s.replace(/^\/\//, '');
  s = s.replace(/^.*@/, '');
  s = s.split(/[/?#]/)[0];
  s = s.replace(/:\d+$/, '');
  s = s.replace(/^www\./, '').replace(/\.$/, '').trim();

  if (!s || !s.includes('.')) return '';
  if (!/^[a-z0-9.-]+$/.test(s)) return '';

  return s;
}

function normalizeLink(raw, baseDomain) {
  if (!raw) return null;

  let value = String(raw).trim();

  if (!value) return null;

  if (/^mailto:/i.test(value)) {
    return value;
  }

  if (/^tel:/i.test(value)) {
    return null;
  }

  if (/^javascript:/i.test(value)) {
    return null;
  }

  if (value.startsWith('//')) {
  value = 'https:' + value;
  } else if (value.startsWith('/')) {
  value = `https://${baseDomain}${value}`;
  }

  if (!/^https?:\/\//i.test(value)) {
    return null;
  }

  value = value.split('#')[0];

  return value;
}

function cleanEmail(value) {
  if (!value) return '';

  let e = String(value)
    .trim()
    .toLowerCase()
    .replace(/^mailto:/i, '')
    .split('?')[0]
    .trim();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) return '';
  if (/^(noreply|no-reply|donotreply|do-not-reply)@/i.test(e)) return '';

  return e;
}

function extractEmailsFromText(text) {
  const emails = new Set();

  const matches =
    String(text || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];

  for (const raw of matches) {
    const email = cleanEmail(raw);
    if (email) emails.add(email);
  }

  return [...emails];
}

function normalizeInstagramUrl(value) {
  if (!value) return '';

  let s = String(value)
    .trim()
    .replace(/\\\//g, '/')
    .replace(/[)\],.'"]+$/g, '')
    .replace(/^http:\/\//i, 'https://');

  if (!/^https?:\/\/(www\.)?instagram\.com\//i.test(s)) {
    return '';
  }

  const lower = s.toLowerCase();

  // Skip posts/reels/stories; keep profile URLs.
  if (/instagram\.com\/(p|reel|stories|explore|accounts)\//i.test(lower)) {
    return '';
  }

  s = s.split('?')[0].split('#')[0];

  if (!s.endsWith('/')) s += '/';

  return s;
}

function extractInstagramFromText(text) {
  const out = new Set();

  const safeText = String(text || '').replace(/\\\//g, '/');

  const urlMatches =
    safeText.match(/https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9_.]+\/?/gi) || [];

  for (const raw of urlMatches) {
    const clean = normalizeInstagramUrl(raw);
    if (clean) out.add(clean);
  }

  const handleRegex = /\b(?:instagram|ig)\s*[:：]\s*@([a-z0-9._]{2,30})/gi;
  let match;

  while ((match = handleRegex.exec(safeText)) !== null) {
    out.add(`https://www.instagram.com/${match[1].toLowerCase()}/`);
  }

  return [...out];
}

function collectCandidateLeads() {
  const leads = [];

  // Preferred source after the pre-crawl CouchDB skip.
  try {
    leads.push(...$('Filter Known Companies Before Crawl').all().map(item => item.json));
  } catch (e) {}

  // Fallback if that node name does not exist or is bypassed.
  try {
    leads.push(...$('Dedupe & Hard Country Filter1').all().map(item => item.json));
  } catch (e) {}

  // Fallback from the batched lookup prep node.
  try {
    const prepItems = $('Prepare Known Company Lookup').all();
    for (const item of prepItems) {
      if (Array.isArray(item.json?.leads)) {
        leads.push(...item.json.leads);
      }
    }
  } catch (e) {}

  const seen = new Set();
  const deduped = [];

  for (const lead of leads) {
    const domain =
      lead.domain ||
      lead.canonical_domain ||
      hostFromUrl(lead.website);

    if (!domain) continue;

    const key = String(domain).toLowerCase();

    if (seen.has(key)) continue;
    seen.add(key);

    deduped.push({
      ...lead,
      domain: key,
      canonical_domain: lead.canonical_domain || key
    });
  }

  return deduped;
}

function findLeadForCrawl(candidateLeads, crawledUrl, index) {
  const crawledHost = hostFromUrl(crawledUrl);

  if (crawledHost) {
    const exact = candidateLeads.find(lead => {
      const leadHost =
        lead.domain ||
        lead.canonical_domain ||
        hostFromUrl(lead.website);

      return String(leadHost || '').toLowerCase() === crawledHost;
    });

    if (exact) return exact;
  }

  return candidateLeads[index] || candidateLeads[0] || {};
}

function extractRawLinksFromHtml(html) {
  const out = [];
  const text = String(html || '');
  const hrefRegex = /\bhref\s*=\s*["']([^"']+)["']/gi;

  let match;

  while ((match = hrefRegex.exec(text)) !== null) {
    out.push(match[1]);
  }

  return out;
}

const candidateLeads = collectCandidateLeads();
const output = [];

for (let index = 0; index < crawlItems.length; index++) {
  const r = crawlItems[index].json || {};

  if (
    r.error ||
    Number(r.statusCode || 0) >= 400 ||
    r.body?.error
  ) {
    continue;
  }

  const crawlPayload =
    r.body && typeof r.body === 'object'
      ? r.body
      : r;

  const x = firstResult(crawlPayload);

  const crawledUrl =
    x?.url ||
    x?.data?.url ||
    r?.url ||
    '';

  const lead = findLeadForCrawl(candidateLeads, crawledUrl, index);

  let markdown =
    x?.markdown?.raw_markdown ??
    x?.markdown?.fit_markdown ??
    x?.markdown ??
    x?.data?.markdown ??
    '';

  if (typeof markdown !== 'string') {
    markdown = JSON.stringify(markdown);
  }

  const html =
    x?.html ||
    x?.data?.html ||
    r?.html ||
    '';

  const textForExtraction = [
    markdown,
    String(html || '').slice(0, 500000)
  ].join('\n');

  const linksRaw = x?.links ?? x?.data?.links ?? {};
  const rawLinks = [];

  function addLink(v) {
    if (!v) return;

    if (typeof v === 'string') {
      rawLinks.push(v);
    } else if (typeof v === 'object') {
      const href = v.href || v.url;
      if (href) rawLinks.push(href);
    }
  }

  if (Array.isArray(linksRaw)) {
    linksRaw.forEach(addLink);
  } else if (linksRaw && typeof linksRaw === 'object') {
    for (const value of Object.values(linksRaw)) {
      if (Array.isArray(value)) value.forEach(addLink);
      else addLink(value);
    }
  }

  rawLinks.push(...extractRawLinksFromHtml(html));

  const baseDomain =
    lead.domain ||
    lead.canonical_domain ||
    hostFromUrl(lead.website) ||
    hostFromUrl(crawledUrl);

  const all_links = [
    ...new Set(
      rawLinks
        .map(link => normalizeLink(link, baseDomain))
        .filter(Boolean)
    )
  ];

  const internal_links = [];
  const external_links = [];
  const mailto_emails = new Set();

  for (const link of all_links) {
    if (/^mailto:/i.test(link)) {
      const email = cleanEmail(link);
      if (email) mailto_emails.add(email);
      continue;
    }

    const host = hostFromUrl(link);

    if (!host) continue;

    if (host === baseDomain) {
      internal_links.push(link);
    } else {
      external_links.push(link);
    }
  }

  const homepage_emails = new Set([
    ...extractEmailsFromText(textForExtraction),
    ...mailto_emails
  ]);

  const instagram_links = new Set([
    ...external_links.map(normalizeInstagramUrl).filter(Boolean),
    ...extractInstagramFromText(textForExtraction)
  ]);

  const social_links = {
    instagram: [...instagram_links]
  };

  output.push({
    json: {
      ...lead,

      website:
        lead.website ||
        crawledUrl ||
        (baseDomain ? `https://${baseDomain}` : ''),

      domain:
        lead.domain ||
        baseDomain,

      canonical_domain:
        lead.canonical_domain ||
        baseDomain,

      crawled_url: crawledUrl,

      homepage_markdown: markdown.slice(0, 12000),
      all_links: all_links.slice(0, 500),
      internal_links: [...new Set(internal_links)].slice(0, 250),
      external_links: [...new Set(external_links)].slice(0, 120),

      instagram_links: [...instagram_links],
      social_links,

      mailto_emails: [...mailto_emails],
      homepage_emails: [...homepage_emails],
      public_emails_found: [...homepage_emails]
    }
  });
}

return output;

const inputItems = $input.all();
const leads = (() => {
  try {
    return $('Normalize Homepage Crawl1').all().map(item => item.json || {});
  } catch (e) {
