  }
})();

const out = [];

const blocked = new Set([
  'japan',
  'indonesia',
  'south korea',
  'republic of korea',
  'thailand',
  'maldives',
  'spain'
]);

const allowed = new Set([
  'scuba_instructor',
  'dmc',
  'tour_operator_travel_agency',
