}

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const parsed = parseDeepSeek(item);
  const lead = leads[i] || item.json?.lead || item.json || {};

  if (!parsed) continue;

  const country = String(
    parsed.business_country ||
    lead.business_country ||
    ''
  ).toLowerCase().trim();

  if (blocked.has(country)) continue;

  const persona = String(parsed.persona || '').trim();

  const categoryText = String(lead.category || '').toLowerCase();
  const companyText = String(lead.company_name || '').toLowerCase();
  const homepageText = String(lead.homepage_markdown || '').toLowerCase();
  const linksText = JSON.stringify((lead.internal_links || []).slice(0, 120)).toLowerCase();

  const combinedText = [
    categoryText,
    companyText,
    homepageText,
    linksText
  ].join(' ');

  const hasDiveBusinessSignal =
    /scuba|diving|dive school|dive centre|dive center|dive club|padi|ssi|bsac|liveaboard|dive safari/.test(combinedText);

  const hasHighValueTravelSignal =
    /liveaboard|live-aboard|dive safari|diving safari|maldives|red sea|dive travel|scuba travel|diving holiday|diving holidays|scuba holiday|scuba holidays|group dive|group trip|overseas diving|dive expedition|yacht|charter/.test(combinedText);

  const personaAllowed = allowed.has(persona);

  const deepseekAccepted =
    personaAllowed &&
    parsed.qualify_for_deep_research === true &&
    (
      Number(parsed.intent_score || 0) >= 35 ||
      Number(parsed.preliminary_icp_score || 0) >= 55
    );

  const softAccepted =
    hasDiveBusinessSignal &&
    hasHighValueTravelSignal;

  if (!deepseekAccepted && !softAccepted) continue;

  out.push({
    json: {
      ...lead,
      prequal: parsed,
      prequal_gate: {
        passed: true,
        budget_mode: 'conservative_v2',
        mode: deepseekAccepted ? 'deepseek_accept' : 'strong_signal_soft_accept',
        original_persona: persona,
        original_qualify_for_deep_research: parsed.qualify_for_deep_research,
        original_intent_score: parsed.intent_score ?? null,
        original_preliminary_icp_score: parsed.preliminary_icp_score ?? null,
        original_reason: parsed.reason || ''
      }
    }
  });
}

return out;

const inputItems = $input.all();
const out = [];

const intentWeights = [
  ['liveaboard',100], ['live-aboard',100],
