function trash(url) {
  return /(privacy|terms|cookie|login|cart|checkout|wp-admin|gift-voucher|basket|account|tag\/|category\/)/i.test(url);
}

function scoreWith(url, weights) {
  const s = String(url || '').toLowerCase();
  if (trash(s)) return -100;
  let best = 0;
  for (const [k,w] of weights) {
    if (s.includes(k)) best = Math.max(best,w);
  }
  return best;
}

function hostFrom(value) {
  const s = String(value || '').trim().toLowerCase();
  const m = s.replace(/^https?:\/\//i, '').split(/[/?#]/)[0];
  return m.replace(/^www\./, '').replace(/:\d+$/, '');
}

function normalizeUrl(raw, website) {
  if (!raw) return '';
  let s = String(raw).trim();
  if (!s || /^(mailto:|tel:|javascript:)/i.test(s)) return '';

  if (s.startsWith('//')) s = 'https:' + s;
  else if (s.startsWith('/')) {
    const baseHost = hostFrom(website);
    if (!baseHost) return '';
    s = 'https://' + baseHost + s;
  } else if (!/^https?:\/\//i.test(s)) {
    const baseHost = hostFrom(website);
    if (!baseHost) return '';
    s = 'https://' + baseHost + '/' + s.replace(/^\/+/, '');
  }

  s = s.split('#')[0];
  return s;
}

function uniqueTop(rows, field, limit) {
  return [...new Map(
    rows
      .filter(x => Number(x[field] || 0) > 0)
      .sort((a,b) => Number(b[field] || 0) - Number(a[field] || 0))
      .map(x => [x.url, x])
  ).values()].slice(0, limit);
}

