    urls.push({
      url: clean,
      intent_score: scoreWith(clean, intentWeights),
      people_score: scoreWith(clean, peopleWeights)
    });
  }

  const selected = [];
  for (const row of uniqueTop(urls, 'intent_score', 2)) selected.push(row);
  for (const row of uniqueTop(urls, 'people_score', 1)) selected.push(row);

  const deduped = [...new Map(selected.map(x => [x.url, x])).values()]
    .slice(0, 3);

  out.push({
