function cleanEmail(value) {
  if (!value) return '';

  let email = String(value)
    .trim()
    .toLowerCase()
    .replace(/^mailto:/i, '')
    .split('?')[0]
    .trim();

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return '';
  if (/^(noreply|no-reply|donotreply|do-not-reply)@/i.test(email)) return '';

  return email;
}

